<?php $editing=!empty($row); ?><div class="panel"><h5 class="fw-bold mb-3"><?= $editing?'Edit':'Tambah' ?> <?= esc(ucfirst($resource)) ?></h5><form method="post" enctype="multipart/form-data" action="<?= $editing?site_url('admin/'.$resource.'/'.$row['id']):site_url('admin/'.$resource) ?>"><?= csrf_field() ?><div class="row g-3"><?php if($resource==='mahasiswa'): ?><div class="col-md-6"><label class="form-label">NIM</label><input class="form-control" name="nim" value="<?= esc(old('nim',$row['nim']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Nama Lengkap</label><input class="form-control" name="nama" value="<?= esc(old('nama',$row['nama']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Angkatan</label><input class="form-control" type="number" name="angkatan" value="<?= esc(old('angkatan',$row['angkatan']??date('Y'))) ?>" required></div><div class="col-md-6"><label class="form-label">Dosen Wali</label><select class="form-select" name="dosen_wali_id"><option value="">Belum ditentukan</option><?php foreach($lecturers as $l): ?><option value="<?= $l['id'] ?>" <?= (string)old('dosen_wali_id',$row['dosen_wali_id']??'')===(string)$l['id']?'selected':'' ?>><?= esc($l['nama'].' ('.$l['nidn'].')') ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Foto <?= $editing?'(opsional)':'(wajib)' ?></label><input class="form-control" type="file" name="foto" accept=".jpg,.jpeg,.png,.webp" <?= $editing?'':'required' ?> onchange="previewFoto(event)"><small class="text-secondary">JPG/PNG/WEBP, maksimal 1 MB.</small></div><div class="col-md-6"><?php if($editing && !empty($row['foto'])): ?><img id="preview" class="avatar" style="width:100px;height:100px" src="<?= base_url('uploads/foto/'.$row['foto']) ?>"><?php else: ?><img id="preview" class="avatar d-none" style="width:100px;height:100px"><?php endif ?></div><?php elseif($resource==='dosen'): ?><div class="col-md-6"><label class="form-label">NIDN</label><input class="form-control" name="nidn" value="<?= esc(old('nidn',$row['nidn']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Nama Lengkap</label><input class="form-control" name="nama" value="<?= esc(old('nama',$row['nama']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?= esc(old('email',$row['email']??'')) ?>"></div><?php else: ?><div class="col-md-4"><label class="form-label">Kode Mata Kuliah</label><input class="form-control" name="kode" value="<?= esc(old('kode',$row['kode']??'')) ?>" required></div><div class="col-md-8"><label class="form-label">Nama Mata Kuliah</label><input class="form-control" name="nama" value="<?= esc(old('nama',$row['nama']??'')) ?>" required></div><div class="col-md-4"><label class="form-label">SKS</label><input class="form-control" type="number" min="1" max="6" name="sks" value="<?= esc(old('sks',$row['sks']??3)) ?>" required></div><div class="col-md-4"><label class="form-label">Semester Kurikulum</label><input class="form-control" type="number" min="1" max="14" name="semester" value="<?= esc(old('semester',$row['semester']??1)) ?>" required></div><div class="col-md-4"><label class="form-label">Kuota</label><input class="form-control" type="number" min="1" name="kuota" value="<?= esc(old('kuota',$row['kuota']??40)) ?>" required></div><div class="col-md-6"><label class="form-label">Dosen Pengampu</label><select class="form-select" name="dosen_id"><option value="">Belum ditentukan</option><?php foreach($lecturers as $l): ?><option value="<?= $l['id'] ?>" <?= (string)old('dosen_id',$row['dosen_id']??'')===(string)$l['id']?'selected':'' ?>><?= esc($l['nama'].' ('.$l['nidn'].')') ?></option><?php endforeach ?></select></div><?php endif ?></div><div class="mt-4"><button class="btn btn-primary">Simpan</button><a class="btn btn-light" href="<?= site_url('admin/'.$resource) ?>">Kembali</a></div></form></div><script>function previewFoto(e){const f=e.target.files[0];if(!f)return;const p=document.getElementById('preview');p.src=URL.createObjectURL(f);p.classList.remove('d-none')}</script>